from math import comb


def countSameBitCount(n):
    k = bin(n).count("1")
    total = 0
    seen = 0
    for i in range(n.bit_length() - 1, -1, -1):
        if (n >> i) & 1:
            need = k - seen
            if 0 <= need <= i:
                total += comb(i, need)
            seen += 1
    return total + 1
